const t=[{id:"l.rc-tank-statics.deep",xp:30,title:{en:"Raise the water to 3 m: the corner moment grows with h³ — more than three times",ar:"علّي المية لـ 3 م: عزم الركن بيكبر مع h³ — أكتر من تلات أضعاف"},check:e=>e.preset==="channel"&&e.mode==="channel"&&!e.tie&&e.h>=2.999999999}],a=[{id:"l.rc-tank-statics.untie",xp:30,title:{en:"Take the tie away: the wall is a cantilever again — compare the corner moment",ar:"شيل الشداد: الحائط رجع كابولي — قارن عزم الركن"},check:e=>e.preset==="channelTie"&&e.mode==="channel"&&!e.tie}],s=[{id:"l.rc-tank-statics.oneway",xp:30,title:{en:"Stretch L₁ past twice the height: walls 1 turn one-way (α₁ = 1)",ar:"طوّل L₁ لأكتر من ضعف الارتفاع: الحوائط 1 بتبقى في اتجاه واحد (α₁ = 1)"},check:e=>e.preset==="rect"&&e.mode==="rect"&&e.a1>=1-1e-9}],o=[{id:"l.rc-tank-statics.square",xp:30,title:{en:"Make the plan square (L₁ = L₂) and compare the two span moments",ar:"خلّي المسقط مربع (L₁ = L₂) وقارن عزمي البحر"},check:e=>e.preset==="rectHz"&&e.mode==="rect"&&e.strip==="hz"&&Math.abs(e.L1-e.L2)<.05}],n=[{id:"l.rc-tank-statics.converge",xp:40,title:{en:"Balance the table until it converges: how much did two cycles miss?",ar:"وازن الجدول لحد ما يتزن: الدورتين فوّتوا قد إيه؟"},check:e=>e.preset==="cells"&&e.mode==="rect"&&e.exact}],r=[{id:"l.rc-tank-statics.stiff",xp:30,title:{en:"Thicken the floor until I_f/I_w passes 8 — what happens at the corner?",ar:"تخّن الأرضية لحد ما I_f/I_w تعدّي 8 — إيه اللي بيحصل عند الركن؟"},check:e=>e.preset==="rested"&&e.mode==="rect"&&e.ratioI>=8}],i=[{id:"l.rc-tank-statics.backfill",xp:30,title:{en:"Raise the backfill to the top of the empty tank",ar:"علّي الردم لحد راس الخزان الفاضي"},check:e=>e.preset==="buried"&&e.mode==="rect"&&e.hg>=e.h-1e-9}],l=[{id:"l.rc-tank-statics.pinned",xp:30,title:{en:"Pin the column bases: where do the lowest hinges go, and the base moment?",ar:"خلّي قواعد الأعمدة مفصلية: آخر مفصلات بتروح فين، وعزم القاعدة؟"},check:e=>e.preset==="staging"&&e.mode==="staging"&&e.stBase==="pinned"}],h=[{id:"l.rc-tank-statics.res-full",xp:30,title:{en:"Fill compartment B again: what happens to the intermediate wall?",ar:"املا العنبر B تاني: إيه اللي بيحصل للحائط الوسطاني؟"},check:e=>e.preset==="reservoir"&&e.mode==="rect"&&e.fill==="full"}],m={sections:[{id:"types",title:{en:"Water tanks and the 1 m strip",ar:"خزانات المية وشريحة الـ 1 م"},blocks:[{t:"p",text:{en:"A water tank is a set of reinforced-concrete **walls** and a **floor** (often with a **roof**) that holds a given volume of water. Tanks are grouped in two ways. By their **position**: **elevated** tanks stand on columns (a staging) to give the water its pressure; **rested** tanks sit on the ground; **underground** (buried) tanks are sunk in the soil, completely or partly. By their **shape**: **rectangular** tanks, **open channels** (a U-shaped trough carried on columns, as in an aqueduct or an irrigation flume) and **circular** tanks, which have their own episode.",ar:"خزان المية عبارة عن **حوائط** و**أرضية** خرسانة مسلحة (وغالبًا **سقف**) بتشيل حجم معين من المية. والخزانات بتتقسم بطريقتين. حسب **مكانها**: الخزانات **العالية** واقفة على أعمدة علشان تدّي المية ضغطها؛ والخزانات **المرتكزة على الأرض** قاعدة على التربة؛ والخزانات **تحت الأرض** مدفونة في التربة كلها أو جزء منها. وحسب **شكلها**: خزانات **مستطيلة**، و**قنوات مفتوحة** (مجرى على شكل U شايلينه أعمدة، زي القناطر وقنوات الري المرفوعة)، وخزانات **دائرية** ولها حلقة لوحدها."}},{t:"table",head:[{en:"Type",ar:"النوع"},{en:"Where you meet it",ar:"بتقابله فين"},{en:"What governs its statics",ar:"إيه اللي بيحكم الاستاتيكا بتاعته"}],rows:[[{en:"elevated",ar:"عالي"},{en:"the water tower of a town or a factory",ar:"برج مية لمدينة أو مصنع"},{en:"water on walls and floor; the walls carry the floor as upturned beams; wind on the staging",ar:"المية على الحوائط والأرضية؛ الحوائط شايلة الأرضية ككمرات مقلوبة؛ الرياح على الأعمدة"}],[{en:"rested on the ground",ar:"مرتكز على الأرض"},{en:"the ground reservoir that feeds a pump",ar:"الخزان الأرضي اللي بيغذّي طلمبة"},{en:"the floor is a footing for the whole tank: the soil pushes it up",ar:"الأرضية قاعدة للخزان كله: التربة بتزقها لفوق"}],[{en:"underground / partly buried",ar:"تحت الأرض / مدفون جزئيًا"},{en:"sumps, sewage tanks, tanks under a pump room",ar:"البيارات وخزانات الصرف والخزانات تحت أوضة الطلمبات"},{en:"earth pressure on the walls when the tank is empty",ar:"ضغط التربة على الحوائط والخزان فاضي"}],[{en:"open channel",ar:"قناة مفتوحة"},{en:"aqueducts, irrigation flumes",ar:"القناطر وقنوات الري المرفوعة"},{en:"a U-strip: two walls and the floor",ar:"شريحة U: حائطين والأرضية"}]]},{t:"p",text:{en:"The statics of every tank starts from one idea: the walls are **vertical slabs** and the floor is a **horizontal slab**. Cut out a **strip 1.0 m wide** and follow the loads on it — the strip becomes a small frame of walls and floor, solved like any frame. Water presses on a wall with an intensity that grows linearly with depth, a **triangle** from zero at the surface to $w_1$ at the floor; the floor carries its own weight plus the whole water column above it:",ar:"استاتيكا أي خزان بتبدأ من فكرة واحدة: الحوائط **بلاطات رأسية** والأرضية **بلاطة أفقية**. اقطع **شريحة عرضها 1.0 م** وتابع الأحمال عليها — الشريحة بتبقى إطار صغير من حوائط وأرضية، بيتحل زي أي إطار. المية بتضغط على الحائط بشدة بتزيد خطيًا مع العمق، **مثلث** من صفر عند السطح لحد $w_1$ عند الأرضية؛ والأرضية شايلة وزنها وعمود المية كله اللي فوقها:"}},{t:"eq",tex:"w_1 = \\gamma_w\\,h,\\qquad w_2 = t_f\\,\\gamma_c + \\gamma_w\\,h,\\qquad \\gamma_w = 10\\ \\text{kN/m}^3,\\quad \\gamma_c = 25\\ \\text{kN/m}^3",caption:{en:"On a 1 m strip, kN/m² and kN/m are the same number. The design water level is taken at the top of the wall (no freeboard) — the safe side.",ar:"على شريحة 1 م، الـ kN/m² والـ kN/m نفس الرقم. ومنسوب المية التصميمي بيتاخد عند راس الحائط (من غير خلوص) — ناحية الأمان."}},{t:"steps",items:[{en:"An open channel 2.2 m deep with a 300 mm floor: $w_1 = 10\\times2.2 = 22$ kN/m at the foot of each wall.",ar:"قناة مفتوحة عمقها 2.2 م وأرضيتها 300 مم: $w_1 = 10\\times2.2 = 22$ kN/m عند رجل كل حائط."},{en:"Floor: $w_2 = 0.30\\times25 + 10\\times2.2 = 7.5 + 22 = 29.5$ kN/m — the water column is almost three times the slab weight.",ar:"الأرضية: $w_2 = 0.30\\times25 + 10\\times2.2 = 7.5 + 22 = 29.5$ kN/m — عمود المية تقريبًا تلات أضعاف وزن البلاطة."}]},{t:"p",text:{en:"**Water on any surface.** At a depth $h$ below the free water level the pressure is $\\gamma_w h$ and it acts **normal** to the surface, whatever its slope. $h$ is always measured to the **free** level: in a closed tank fed by a pipe that rises above the roof, to the water level in the pipe — then even the roof is pressed, upwards. On a sloping or curved surface the pressure has a simple vertical resultant. On an element $dA$ at the slope $\\phi$, the force $\\gamma_w h\\,dA$ has the vertical part $\\gamma_w h\\,dA\\cos\\phi = \\gamma_w h\\,dA_p$ ($dA_p$ its plan) — exactly the weight of the water column standing on that element. Added up: the vertical push on a surface equals the **weight of the water directly above it** up to the free level. When the water is under the surface (a roof, a cover, a shell over the water), the same column counts as **virtual** water, and it pushes **upwards**.",ar:"**المية على أي سطح.** على عمق $h$ تحت منسوب المية الحر الضغط $\\gamma_w h$ وشغال **عمودي** على السطح، مهما كان ميله. و $h$ دايمًا بيتقاس لحد المنسوب **الحر**: في خزان مقفول متغذّي بماسورة طالعة فوق السقف، لحد منسوب المية في الماسورة — وساعتها حتى السقف بيتضغط، لفوق. وعلى سطح مايل أو منحني الضغط ليه محصلة رأسية بسيطة. على جزء $dA$ ميله $\\phi$، القوة $\\gamma_w h\\,dA$ مركبتها الرأسية $\\gamma_w h\\,dA\\cos\\phi = \\gamma_w h\\,dA_p$ ($dA_p$ مسقطه) — بالظبط وزن عمود المية الواقف على الجزء ده. ولو جمعناهم: الزق الرأسي على السطح = **وزن المية اللي فوقه مباشرة** لحد المنسوب الحر. ولو المية تحت السطح (سقف، أو غطا، أو قشرة فوق المية)، نفس العمود بيتحسب **مية وهمية**، وبيزق **لفوق**."}},{t:"eq",tex:"p = \\gamma_w h,\\qquad dP_v = \\gamma_w h\\,dA\\cos\\phi = \\gamma_w h\\,dA_p,\\qquad P_v = \\gamma_w V,\\qquad P_h = \\dfrac{\\gamma_w h^2}{2}",caption:{en:"V: the real or virtual volume of water between the surface and the free level, directly above (or below) it. P_h: the horizontal push per metre of a wall holding h of water, on its vertical projection, whatever its slope.",ar:"V: حجم المية الحقيقي أو الوهمي بين السطح والمنسوب الحر، فوقه (أو تحته) مباشرة. و P_h: الزق الأفقي لكل متر من حائط شايل h مية، على مسقطه الرأسي، مهما كان ميله."}},{t:"p",text:{en:"**Two load cases, never added.** A member that holds water is designed for the tank **full** — its own weight plus the water — and for the tank **empty** — its own weight plus the live load of people and equipment during cleaning and maintenance. The live load is **not** added to the water: nobody walks on a full tank floor. A member that never touches the water (a cover slab) carries its own weight plus the live load only.",ar:"**حالتين تحميل، مبيتجمعوش.** العضو اللي شايل مية بيتصمم والخزان **مليان** — وزنه ومعاه المية — والخزان **فاضي** — وزنه ومعاه الحمل الحي بتاع الناس والمعدات وقت التنضيف والصيانة. والحمل الحي **مبيتضافش** على المية: محدش بيمشي على أرضية خزان مليان. والعضو اللي عمره ما بيلمس المية (بلاطة الغطا) بيشيل وزنه والحمل الحي بس."}},{t:"steps",items:[{en:"A wall that leans outwards at 60° to the horizontal (the tank widens upwards) holds 2.4 m of water. At its foot $p = 10\\times2.4 = 24$ kN/m², normal to the wall, over a sloping length $2.4/\\sin60^\\circ = 2.771$ m: resultant $\\tfrac12\\times24\\times2.771 = 33.26$ kN per metre.",ar:"حائط مايل لبرّه بزاوية 60° على الأفقي (الخزان بيوسع لفوق) شايل 2.4 م مية. عند رجله $p = 10\\times2.4 = 24$ kN/m²، عمودي على الحائط، على طول مايل $2.4/\\sin60^\\circ = 2.771$ م: المحصلة $\\tfrac12\\times24\\times2.771 = 33.26$ kN لكل متر."},{en:"Its parts: horizontally $\\gamma_w h^2/2 = 28.8$ kN, exactly as on a vertical wall; vertically the weight of the water wedge standing on the wall, $\\tfrac12\\times2.4\\times\\dfrac{2.4}{\\tan60^\\circ} = 1.663$ m² → 16.63 kN, downwards. Check: $\\sqrt{28.8^2 + 16.63^2} = 33.26$ kN.",ar:"مركباتها: أفقي $\\gamma_w h^2/2 = 28.8$ kN، بالظبط زي الحائط الرأسي؛ ورأسي وزن خابور المية الواقف على الحائط، $\\tfrac12\\times2.4\\times\\dfrac{2.4}{\\tan60^\\circ} = 1.663$ م² ← 16.63 kN، لتحت. المراجعة: $\\sqrt{28.8^2 + 16.63^2} = 33.26$ kN."}]},{t:"quiz",q:{kind:"num",q:{en:"A tank 3.2 m deep has a 300 mm floor. The floor load w₂ on a 1 m strip (kN/m)?",ar:"خزان عمقه 3.2 م وأرضيته 300 مم. حمل الأرضية w₂ على شريحة 1 م (kN/m)؟"},answer:39.5,tol:.003,unit:"kN/m",explain:{en:"$w_2 = 0.3\\times25 + 10\\times3.2 = 7.5 + 32 = 39.5$ kN/m.",ar:"$w_2 = 0.3\\times25 + 10\\times3.2 = 7.5 + 32 = 39.5$ kN/m."}}}]},{id:"channel",title:{en:"The open channel: cantilever walls",ar:"القناة المفتوحة: حوائط كابولي"},blocks:[{t:"p",text:{en:"Cut a 1 m strip across an open channel and you get a **U**: two walls standing on the floor. Draw it with a support under each corner — and remember what those supports mean. **They are not columns.** The real columns are far apart along the channel; between them each wall works as a deep **upturned beam** that carries the floor. The supports only say that the corners do not go down.",ar:"اقطع شريحة 1 م على عرض قناة مفتوحة هيطلعلك **U**: حائطين واقفين على الأرضية. ارسمها بركيزة تحت كل ركن — وافتكر الركائز دي معناها إيه. **دي مش أعمدة.** الأعمدة الحقيقية بعيدة عن بعض على طول القناة؛ وبينهم كل حائط شغال **ككمرة مقلوبة** عميقة شايلة الأرضية. الركائز بتقول بس إن الأركان مش بتنزل."}},{t:"p",text:{en:"The corner joint is **rigid**, so the moment at the foot of the wall, $M_b$, passes whole into the floor. The water pushes each wall outwards; the base shear $x$ of the wall pulls on the floor, so the floor is in **tension** $x$. The floor reaction $y$ hangs from the wall: the wall is in **tension** too, $y$ at its foot, falling to **zero at the top** — the wall, a deep beam spanning between the columns, carries the floor load up to them by **arch action**, so the hanger force fades as it climbs.",ar:"عقدة الركن **جاسئة**، فالعزم عند رجل الحائط $M_b$ بيعدّي كله للأرضية. المية بتزق كل حائط لبرّه؛ وقص قاعدة الحائط $x$ بيشد الأرضية، فالأرضية بتبقى **شد** بقيمة $x$. ورد فعل الأرضية $y$ متعلق في الحائط: فالحائط **مشدود** برضه، $y$ عند رجله وبيقل لحد **صفر عند الراس** — الحائط كمرة عميقة بين الأعمدة، بيطلّع حمل الأرضية ليهم **بعمل القوس**، فقوة التعليق بتتلاشى وهي طالعة."}},{t:"eq",tex:"x = \\dfrac{w_1h}{2},\\qquad M_b = x\\,\\dfrac{h}{3} = \\dfrac{w_1h^2}{6},\\qquad y = \\dfrac{w_2L}{2},\\qquad M_{mid} = \\dfrac{w_2L^2}{8} - M_b",caption:{en:"x acts at h/3 above the base. The floor diagram is the parabola w₂L²/8 hung from the closing line at M_b.",ar:"x شغالة على h/3 فوق القاعدة. ومنحنى الأرضية هو القطع المكافئ w₂L²/8 متعلق من خط القفل عند M_b."}},{t:"note",tone:"info",text:{en:"Drawing rules for every tank: the **B.M.D. on the tension side** of each member; the **N.F.D.** with tension +. The wall moment of the open channel puts the **water face in tension** at the corner; the floor is in tension at the bottom only if its mid-span moment stays positive.",ar:"قواعد الرسم في كل الخزانات: **منحنى العزوم على ناحية الشد** لكل عضو؛ و**منحنى القوى العمودية** والشد +. عزم الحائط في القناة المفتوحة بيعمل **شد على وش المية** عند الركن؛ والأرضية بيبقى تحتها شد بس لو عزم نص البحر فضل موجب."}},{t:"steps",items:[{en:"A channel 2.0 m deep, 3.0 m between the wall axes, floor 250 mm: $w_1 = 20$ kN/m, $w_2 = 0.25\\times25 + 20 = 26.25$ kN/m.",ar:"قناة عمقها 2.0 م، و 3.0 م بين محاور الحوائط، وأرضية 250 مم: $w_1 = 20$ kN/m، و $w_2 = 0.25\\times25 + 20 = 26.25$ kN/m."},{en:"Wall: $x = 20\\times2.0/2 = 20$ kN at 0.67 m above the floor, $M_b = 20\\times2.0^2/6 = 13.33$ kN.m — tension on the water face.",ar:"الحائط: $x = 20\\times2.0/2 = 20$ kN على 0.67 م فوق الأرضية، و $M_b = 20\\times2.0^2/6 = 13.33$ kN.m — شد على وش المية."},{en:"Floor: $y = 26.25\\times3/2 = 39.38$ kN; $M_{mid} = 26.25\\times3^2/8 - 13.33 = 29.53 - 13.33 = 16.20$ kN.m, tension at the bottom.",ar:"الأرضية: $y = 26.25\\times3/2 = 39.38$ kN؛ و $M_{mid} = 26.25\\times3^2/8 - 13.33 = 29.53 - 13.33 = 16.20$ kN.m، شد تحت."},{en:"N.F.D.: the floor carries 20 kN of tension along its whole length; each wall 39.38 kN at its foot, falling to zero at its top.",ar:"منحنى القوى العمودية: الأرضية عليها 20 kN شد على طولها كله؛ وكل حائط 39.38 kN عند رجله وبيقل لصفر عند راسه."}]},{t:"lab",lab:"tank",height:480,props:{preset:"channel",missions:t,defaultTab:"results"},caption:{en:"The channel of the example: the 1 m strip is drawn solid and bent (exaggerated), blue where the water face is in tension. Below: loads, B.M.D., N.F.D.",ar:"قناة المثال: شريحة الـ 1 م مرسومة مصمتة ومنحنية (بمبالغة)، والأزرق مكان الشد على وش المية. وتحت: الأحمال ومنحنى العزوم والقوى العمودية."}},{t:"quiz",q:{kind:"num",q:{en:"A cantilever channel wall holds 2.4 m of water. Its corner moment M_b (kN.m per metre)?",ar:"حائط قناة كابولي شايل 2.4 م مية. عزم الركن M_b (kN.m للمتر)؟"},answer:23.04,tol:.003,unit:"kN.m",explain:{en:"$w_1 = 24$ kN/m, $M_b = 24\\times2.4^2/6 = 23.04$ kN.m.",ar:"$w_1 = 24$ kN/m، و $M_b = 24\\times2.4^2/6 = 23.04$ kN.m."}}}]},{id:"tie",title:{en:"Walls propped by a top beam and a tie — moment distribution",ar:"حوائط مسنودة بكمرة علوية وشداد — توزيع العزوم"},blocks:[{t:"p",text:{en:"A cantilever wall grows heavy fast: $M_b$ grows with $h^3$. Deeper channels get a **horizontal beam along the top of each wall**, and the two beams are tied across by **ties** every few metres — the two top beams balance each other through the ties. For the 1 m strip, the top of the wall is now a **horizontal support** (a hinge), the strip is statically indeterminate, and we solve it by **moment distribution**. Here is the method again, as the tanks need it:",ar:"الحائط الكابولي بيتقل بسرعة: $M_b$ بتكبر مع $h^3$. القنوات الأعمق بتاخد **كمرة أفقية على راس كل حائط**، والكمرتين متربطين بـ **شدادات** كل كام متر — الكمرتين العلويتين بيوازنوا بعض عن طريق الشدادات. وبالنسبة لشريحة الـ 1 م، راس الحائط بقى **ركيزة أفقية** (مفصل)، والشريحة بقت غير محددة استاتيكيًا، وبنحلها بـ **توزيع العزوم**. ودي الطريقة تاني زي ما الخزانات محتاجاها:"}},{t:"table",head:[{en:"Member",ar:"العضو"},{en:"Relative stiffness K",ar:"الجساءة النسبية K"},{en:"Carry-over",ar:"الترحيل"}],rows:[[{en:"both ends fixed or continuous",ar:"الطرفين ثابتين أو مستمرين"},"I/L","½"],[{en:"far end hinged (a propped wall)",ar:"الطرف البعيد مفصلي (حائط مسنود)"},"0.75 I/L",{en:"none",ar:"مفيش"}],[{en:"symmetric member (cut by the axis of symmetry)",ar:"عضو متماثل (محور التماثل بيقطعه)"},"0.5 I/L",{en:"none",ar:"مفيش"}],[{en:"cantilever",ar:"كابولي"},{en:"D.f. = 0",ar:"D.f. = 0"},"—"]]},{t:"eq",tex:"D.f._{ab} = \\dfrac{K_{ab}}{\\sum K}",caption:{en:"At a fixed support and for a cantilever the distribution factor is zero. In a symmetric strip only half is analysed (the scissors symbol marks the axis); the member cut by the axis is a symmetric member.",ar:"عند ركيزة ثابتة وللكابولي معامل التوزيع صفر. وفي الشريحة المتماثلة بنحل النص بس (علامة المقص بتحدد المحور)؛ والعضو اللي المحور بيقطعه عضو متماثل."}},{t:"table",head:[{en:"Load and supports",ar:"الحمل والركائز"},{en:"Fixed-end moment",ar:"عزم التثبيت"}],rows:[[{en:"uniform w, both ends fixed",ar:"حمل موزع منتظم w، الطرفين ثابتين"},{en:"wL²/12 at each end",ar:"wL²/12 عند كل طرف"}],[{en:"uniform w, fixed – hinged",ar:"حمل موزع منتظم w، ثابت – مفصلي"},"wL²/8"],[{en:"full triangle 0 → w, both ends fixed",ar:"مثلث كامل 0 ← w، الطرفين ثابتين"},{en:"wh²/30 at the zero end, wh²/20 at the peak end",ar:"wh²/30 عند طرف الصفر، و wh²/20 عند طرف القمة"}],[{en:"full triangle, hinged at the zero end",ar:"مثلث كامل، مفصلي عند طرف الصفر"},{en:"wh²/15 at the fixed end",ar:"wh²/15 عند الطرف الثابت"}],[{en:"triangle over the bottom h/4 only (w at the base), both ends fixed",ar:"مثلث على الربع السفلي h/4 بس (w عند القاعدة)، الطرفين ثابتين"},{en:"wh²/124 at the base, wh²/904 at the top",ar:"wh²/124 عند القاعدة، و wh²/904 عند الراس"}],[{en:"the same, top hinged",ar:"نفسه والراس مفصلي"},{en:"wh²/117 at the base",ar:"wh²/117 عند القاعدة"}],[{en:"span hinged at b carrying a cantilever moment M there, fixed at c, uniform w",ar:"بحر مفصلي عند b وعليه عزم كابولي M هناك، وثابت عند c، وحمل موزع منتظم w"},"wL²/8 − M/2"]]},{t:"p",text:{en:"**Sign convention:** an end moment turning **clockwise is +**, anticlockwise −. The table is set out in rows: D.f., F.E.M., Bal.M. (balance each joint: minus the sum times the D.f.), C.O.M. (half of it goes to the far end — none to a hinge or across the axis), Bal.M. again, and $M_f$, the sum of the column. By hand **two cycles** are usually enough.",ar:"**اصطلاح الإشارات:** عزم الطرف اللي **مع عقارب الساعة +**، وعكسها −. والجدول بيترتب صفوف: D.f.، ثم F.E.M.، ثم Bal.M. (اتزان كل عقدة: سالب المجموع في D.f.)، ثم C.O.M. (نصه بيروح للطرف البعيد — ولا حاجة للمفصل ولا عبر المحور)، ثم Bal.M. تاني، ثم $M_f$ مجموع العمود. وباليد **دورتين** غالبًا كفاية."}},{t:"p",text:{en:"With $M_f$ known, the wall is a beam hinged at the top: take **moments about the top** to get the base reaction $R_b$, then $R_a = W - R_b$ (the tie force per metre). The largest span moment is where the **shear is zero**, at depth $x$ below the top:",ar:"بعد ما $M_f$ اتعرف، الحائط كمرة مفصلية من فوق: خد **العزوم حوالين الراس** تطلع رد فعل القاعدة $R_b$، وبعدين $R_a = W - R_b$ (قوة الشداد لكل متر). وأكبر عزم في البحر عند **القص = صفر**، على عمق $x$ تحت الراس:"}},{t:"eq",tex:"\\dfrac{x}{h}\\,w\\,\\dfrac{x}{2} = R_a \\;\\Rightarrow\\; M^+ = R_a\\,x - \\dfrac{x}{h}\\,w\\,\\dfrac{x^2}{6}",caption:{en:"When the top is also restrained (a roof cast with the wall), add its end moment to M⁺ with its sign.",ar:"ولو الراس كمان متثبت (سقف مصبوب مع الحائط)، زوّد عزم طرفه على M⁺ بإشارته."}},{t:"steps",items:[{en:"A channel 3.0 m deep, 3.5 m wide, walls and floor 300 mm, tops tied: $w_1 = 30$, $w_2 = 0.3\\times25 + 30 = 37.5$ kN/m. Same thickness, so the same $I$.",ar:"قناة عمقها 3.0 م، وعرضها 3.5 م، والحوائط والأرضية 300 مم، والرووس مربوطة: $w_1 = 30$، و $w_2 = 0.3\\times25 + 30 = 37.5$ kN/m. نفس التخانة، يعني نفس $I$."},{en:"Joint b: $K_{ba} = 0.75I/3 = 0.250I$ (hinged top), $K_{bc} = 0.5I/3.5 = 0.143I$ (symmetric floor) → D.f. 0.636 and 0.364.",ar:"العقدة b: $K_{ba} = 0.75I/3 = 0.250I$ (راس مفصلي)، و $K_{bc} = 0.5I/3.5 = 0.143I$ (أرضية متماثلة) ← D.f. = 0.636 و 0.364."},{en:"F.E.M.: $FEM_{ba} = 30\\times3^2/15 = +18.00$, $FEM_{bc} = -37.5\\times3.5^2/12 = -38.28$ kN.m. Balance: $+20.28\\times0.636 = +12.91$ and $+20.28\\times0.364 = +7.38$ → $M_f = 30.91$ kN.m.",ar:"عزوم التثبيت: $FEM_{ba} = 30\\times3^2/15 = +18.00$، و $FEM_{bc} = -37.5\\times3.5^2/12 = -38.28$ kN.m. الاتزان: $+20.28\\times0.636 = +12.91$ و $+20.28\\times0.364 = +7.38$ ← $M_f = 30.91$ kN.m."},{en:"Wall: $W = 30\\times3/2 = 45$ kN at 2.0 m below the top. $R_b = (45\\times2 + 30.91)/3 = 40.30$ kN, $R_a = 4.70$ kN (the tie force per metre).",ar:"الحائط: $W = 30\\times3/2 = 45$ kN على 2.0 م تحت الراس. $R_b = (45\\times2 + 30.91)/3 = 40.30$ kN، و $R_a = 4.70$ kN (قوة الشداد لكل متر)."},{en:"Zero shear: $10x\\cdot x/2 = 4.70$ → $x = 0.97$ m; $M^+ = 4.70\\times0.97 - 10\\times0.97^3/6 = 3.04$ kN.m, tension on the dry face.",ar:"القص صفر: $10x\\cdot x/2 = 4.70$ ← $x = 0.97$ م؛ و $M^+ = 4.70\\times0.97 - 10\\times0.97^3/6 = 3.04$ kN.m، شد على الوش الناشف."},{en:"Floor: $y = 37.5\\times3.5/2 = 65.63$ kN; mid-span $37.5\\times3.5^2/8 - 30.91 = 57.42 - 30.91 = 26.52$ kN.m. N.F.D.: floor tension $R_b = 40.30$ kN; wall tension 65.63 kN at the foot, fading to zero at the top. Without the tie the corner would carry $30\\times3^2/6 = 45$ kN.m.",ar:"الأرضية: $y = 37.5\\times3.5/2 = 65.63$ kN؛ ونص البحر $37.5\\times3.5^2/8 - 30.91 = 57.42 - 30.91 = 26.52$ kN.m. القوى العمودية: شد الأرضية $R_b = 40.30$ kN؛ وشد الحائط 65.63 kN عند رجله وبيتلاشى لصفر عند راسه. من غير الشداد كان الركن هيشيل $30\\times3^2/6 = 45$ kN.m."}]},{t:"lab",lab:"tank",height:480,props:{preset:"channelTie",missions:a,defaultTab:"steps"},caption:{en:"The propped channel: follow the distribution table row by row under the drawings.",ar:"القناة المسنودة: تابع جدول توزيع العزوم صف بصف تحت المنحنيات."}},{t:"quiz",q:{kind:"num",q:{en:"A wall 3 m high hinged at the top meets a symmetric floor 4 m wide; both have the same I. The wall D.f. at the corner?",ar:"حائط ارتفاعه 3 م ومفصلي من فوق بيقابل أرضية متماثلة عرضها 4 م؛ الاتنين ليهم نفس I. الـ D.f. للحائط عند الركن؟"},answer:.667,tol:.005,explain:{en:"$K_{wall} = 0.75I/3 = 0.25I$, $K_{floor} = 0.5I/4 = 0.125I$: $D.f. = 0.25/0.375 = 0.667$.",ar:"$K_{wall} = 0.75I/3 = 0.25I$، و $K_{floor} = 0.5I/4 = 0.125I$: يعني $D.f. = 0.25/0.375 = 0.667$."}}}]},{id:"twoway",title:{en:"Rectangular tanks: two-way walls and the h/4 rule",ar:"الخزانات المستطيلة: حوائط في اتجاهين وقاعدة h/4"},blocks:[{t:"p",text:{en:"The walls of an open channel span one way — vertically. The walls of a rectangular tank are slabs held on three or four sides (the floor, the neighbouring walls, the roof or top beams), so, like floor slabs, they work **one way or two ways depending on their proportions**. In a two-way wall the water triangle splits: a share $\\alpha$ goes **vertically** and $\\beta = 1 - \\alpha$ **horizontally**. $\\alpha$ and $\\beta$ follow the two-way slab rules; here we take Grashoff, as the slabs episode does for heavy loads (water is one), with a panel longer than twice its height working one way:",ar:"حوائط القناة المفتوحة بتشتغل في اتجاه واحد — رأسي. لكن حوائط الخزان المستطيل بلاطات مرتكزة على تلات أو أربع جهات (الأرضية والحوائط اللي جنبها والسقف أو الكمرات العلوية)، فزي بلاطات الأرضيات بتشتغل **في اتجاه واحد أو اتجاهين حسب أبعادها**. وفي الحائط اللي بيشتغل في اتجاهين مثلث المية بيتقسم: نصيب $\\alpha$ بيروح **رأسي** و $\\beta = 1 - \\alpha$ **أفقي**. و $\\alpha$ و $\\beta$ ماشيين على قواعد البلاطات في اتجاهين؛ وهنا بناخد جراشوف، زي حلقة البلاطات مع الأحمال التقيلة (والمية منها)، واللوح اللي طوله أكبر من ضعف ارتفاعه بيشتغل في اتجاه واحد:"}},{t:"eq",tex:"\\alpha = \\dfrac{L^4}{L^4 + h^4},\\qquad \\beta = \\dfrac{h^4}{L^4 + h^4},\\qquad \\alpha_f = \\dfrac{L_1^4}{L_1^4 + L_2^4}",caption:{en:"α: the vertical share of a wall of length L and height h. α_f: the share of the floor spanning L₂ (the shorter span takes more).",ar:"α: النصيب الرأسي لحائط طوله L وارتفاعه h. و α_f: نصيب الأرضية اللي بيشيل على L₂ (البحر الأقصر بياخد أكتر)."}},{t:"p",text:{en:"**The h/4 rule.** The junction of the wall and the floor is very rigid, so right at the base the wall cannot span horizontally: **the whole pressure $\\gamma_w h$ goes vertically at the base**. The extra vertical share $\\beta\\,\\gamma_w h$ fades linearly to zero at **h/4 above the floor**. So the vertical strip carries the triangle $\\alpha\\,\\gamma_w h$ plus a small triangle over the bottom quarter; the horizontal direction carries $\\beta\\,\\gamma_w z$ down to a depth of $0.75h$ and then less, down to zero at the base — it is largest at $h/4$ above the floor:",ar:"**قاعدة h/4.** اتصال الحائط بالأرضية جاسئ جدًا، فعند القاعدة بالظبط الحائط ما يقدرش يشيل أفقي: **الضغط كله $\\gamma_w h$ بيروح رأسي عند القاعدة**. والنصيب الرأسي الزيادة $\\beta\\,\\gamma_w h$ بيقل خطيًا لحد صفر عند **h/4 فوق الأرضية**. يعني الشريحة الرأسية بتشيل المثلث $\\alpha\\,\\gamma_w h$ ومعاه مثلث صغير على الربع السفلي؛ والاتجاه الأفقي بيشيل $\\beta\\,\\gamma_w z$ لحد عمق $0.75h$ وبعدين أقل، لحد صفر عند القاعدة — وأكبر قيمة ليه عند $h/4$ فوق الأرضية:"}},{t:"eq",tex:"q_{h/4} = \\beta\\,\\gamma_w\\,(0.75h) = 0.75\\,\\beta\\,\\gamma_w h"},{t:"p",text:{en:"Three strips then describe the whole tank (walls 1 run along $L_1$, walls 2 along $L_2$): **vertical strip 1** — wall 1, floor, wall 1 — spans $L_2$ with the floor share $\\alpha_f w_2$; **vertical strip 2** spans $L_1$ with $\\beta_f w_2$; and the **horizontal strip at h/4**, a closed frame $L_1\\times L_2$ loaded with $0.75\\,\\beta_1\\gamma_w h$ on walls 1 and $0.75\\,\\beta_2\\gamma_w h$ on walls 2. The tops are held by the roof or the top beams, so the walls are hinged there. (A simpler variant uses one pair for the whole tank: the vertical share $\\alpha$ of walls 1 is the horizontal share of walls 2 and the floor share across $L_2$ — roles swapped for walls 2. Here each wall and the floor get their own shares from their own proportions; the method is the same.)",ar:"وبعدين تلات شرايح بتوصف الخزان كله (الحوائط 1 ماشية على $L_1$، والحوائط 2 على $L_2$): **الشريحة الرأسية 1** — حائط 1 وأرضية وحائط 1 — على بحر $L_2$ ونصيب الأرضية $\\alpha_f w_2$؛ و**الشريحة الرأسية 2** على بحر $L_1$ بـ $\\beta_f w_2$؛ و**الشريحة الأفقية عند h/4**، إطار مقفول $L_1\\times L_2$ عليه $0.75\\,\\beta_1\\gamma_w h$ على الحوائط 1 و $0.75\\,\\beta_2\\gamma_w h$ على الحوائط 2. والرووس ماسكها السقف أو الكمرات العلوية، فالحوائط مفصلية هناك. (فيه طريقة أبسط بتستخدم زوج واحد للخزان كله: النصيب الرأسي $\\alpha$ للحوائط 1 هو النصيب الأفقي للحوائط 2 ونصيب الأرضية على $L_2$ — والأدوار بتتبدل للحوائط 2. وهنا كل حائط والأرضية بياخدوا أنصبتهم من أبعادهم هم؛ والطريقة واحدة.)"}},{t:"note",tone:"info",text:{en:"The fixed-end moments of the bottom-h/4 triangle are $wh^2/124$ at the base and $wh^2/904$ at the top, $wh^2/117$ with the top hinged. The exact integrals give 124.9, 903.5 and 116.8 — the rounded values are used in the tables.",ar:"عزوم التثبيت لمثلث الربع السفلي h/4 هي $wh^2/124$ عند القاعدة و $wh^2/904$ عند الراس، و $wh^2/117$ لو الراس مفصلي. والتكامل المضبوط بيدّي 124.9 و 903.5 و 116.8 — وبنستخدم القيم المقرّبة في الجداول."}},{t:"steps",items:[{en:"An elevated tank 6.0 × 4.5 m (axes), 3.5 m deep, walls and floor 300 mm. Walls 1 (6.0 m long): $\\alpha_1 = 6^4/(6^4 + 3.5^4) = 0.896$; walls 2 (4.5 m): $\\alpha_2 = 0.732$; floor across $L_2$: $\\alpha_f = 6^4/(6^4 + 4.5^4) = 0.760$.",ar:"خزان عالي 6.0 × 4.5 م (محاور)، وعمقه 3.5 م، والحوائط والأرضية 300 مم. الحوائط 1 (طولها 6.0 م): $\\alpha_1 = 6^4/(6^4 + 3.5^4) = 0.896$؛ والحوائط 2 (4.5 م): $\\alpha_2 = 0.732$؛ والأرضية على $L_2$: $\\alpha_f = 6^4/(6^4 + 4.5^4) = 0.760$."},{en:"Strip 1: wall triangle $0.896\\times35 = 31.37$ kN/m, bottom-h/4 triangle $0.104\\times35 = 3.63$ kN/m over 0.875 m; floor $0.760\\times(0.3\\times25 + 35) = 0.760\\times42.5 = 32.29$ kN/m.",ar:"الشريحة 1: مثلث الحائط $0.896\\times35 = 31.37$ kN/m، ومثلث الربع السفلي $0.104\\times35 = 3.63$ kN/m على 0.875 م؛ والأرضية $0.760\\times(0.3\\times25 + 35) = 0.760\\times42.5 = 32.29$ kN/m."},{en:"D.f.: $K_{ba} = 0.75I/3.5 = 0.214I$, $K_{bc} = 0.5I/4.5 = 0.111I$ → 0.66 and 0.34. F.E.M.: $31.37\\times3.5^2/15 + 3.63\\times3.5^2/117 = 25.62 + 0.38 = 26.00$; $-32.29\\times4.5^2/12 = -54.48$ kN.m.",ar:"معاملات التوزيع: $K_{ba} = 0.75I/3.5 = 0.214I$، و $K_{bc} = 0.5I/4.5 = 0.111I$ ← 0.66 و 0.34. عزوم التثبيت: $31.37\\times3.5^2/15 + 3.63\\times3.5^2/117 = 25.62 + 0.38 = 26.00$؛ و $-32.29\\times4.5^2/12 = -54.48$ kN.m."},{en:"Balance: $+18.80$ and $+9.68$ → $M_f = 44.80$ kN.m (water face in tension). Wall: $R_a = 5.63$, $R_b = 50.85$ kN, zero shear 1.12 m below the top, $M^+ = 4.21$ kN.m. Floor: $y = 72.64$ kN, mid-span $32.29\\times4.5^2/8 - 44.80 = 36.93$ kN.m.",ar:"الاتزان: $+18.80$ و $+9.68$ ← $M_f = 44.80$ kN.m (شد على وش المية). الحائط: $R_a = 5.63$، و $R_b = 50.85$ kN، والقص صفر على 1.12 م تحت الراس، و $M^+ = 4.21$ kN.m. الأرضية: $y = 72.64$ kN، ونص البحر $32.29\\times4.5^2/8 - 44.80 = 36.93$ kN.m."}]},{t:"lab",lab:"tank",height:480,props:{preset:"rect",missions:s,defaultTab:"steps"},caption:{en:"The tank of the example, vertical strip 1. Switch to strip 2 or to the frame at h/4 — the same tank, other strips.",ar:"خزان المثال، الشريحة الرأسية 1. بدّل للشريحة 2 أو للإطار عند h/4 — نفس الخزان وشرايح تانية."}},{t:"quiz",q:{kind:"num",q:{en:"A wall 3 m high has a horizontal share β = 0.3. The load on the horizontal strip at h/4 (kN/m)?",ar:"حائط ارتفاعه 3 م ونصيبه الأفقي β = 0.3. الحمل على الشريحة الأفقية عند h/4 (kN/m)؟"},answer:6.75,tol:.003,unit:"kN/m",explain:{en:"$q = 0.75\\,\\beta\\,\\gamma_w h = 0.75\\times0.3\\times10\\times3 = 6.75$ kN/m.",ar:"$q = 0.75\\,\\beta\\,\\gamma_w h = 0.75\\times0.3\\times10\\times3 = 6.75$ kN/m."}}}]},{id:"hz",title:{en:"The horizontal closed frame at h/4",ar:"الإطار الأفقي المقفول عند h/4"},blocks:[{t:"p",text:{en:"Cut the tank horizontally at $h/4$ above the floor, where the horizontal load is largest: the four walls form a **closed rectangular frame**, every wall pushed outwards, every corner rigid. With a symmetric load the frame is symmetric about both axes, so **one corner** is enough and both members meeting there are **symmetric members** ($K = 0.5I/L$). The corners have tension on the water face; the mid-spans on the dry face.",ar:"اقطع الخزان أفقي عند $h/4$ فوق الأرضية، مكان ما الحمل الأفقي أكبر: الأربع حوائط بيعملوا **إطار مستطيل مقفول**، كل حائط متزقوق لبرّه وكل ركن جاسئ. ومع حمل متماثل الإطار متماثل حوالين المحورين، فـ **ركن واحد** كفاية والعضوين اللي بيتقابلوا فيه **أعضاء متماثلة** ($K = 0.5I/L$). والأركان عليها شد على وش المية؛ ونصوص البحور على الوش الناشف."}},{t:"p",text:{en:"The walls of this frame are all in **tension**: each wall is pulled at its two ends by the end shears of its neighbours. On a symmetric frame those shears are simply $qL/2$:",ar:"حوائط الإطار ده كلها **شد**: كل حائط متشد من طرفيه بقص الأطراف بتاع الحوائط اللي جنبه. وفي الإطار المتماثل القص ده ببساطة $qL/2$:"}},{t:"eq",tex:"N_1 = \\dfrac{q_2L_2}{2},\\qquad N_2 = \\dfrac{q_1L_1}{2},\\qquad M_{mid} = \\dfrac{qL^2}{8} - M_{corner}"},{t:"steps",items:[{en:"The same tank at $h/4$: $q_1 = 0.75\\times0.104\\times35 = 2.72$ kN/m on walls 1 (6.0 m), $q_2 = 0.75\\times0.268\\times35 = 7.03$ kN/m on walls 2 (4.5 m) — the long walls send little horizontally.",ar:"نفس الخزان عند $h/4$: $q_1 = 0.75\\times0.104\\times35 = 2.72$ kN/m على الحوائط 1 (6.0 م)، و $q_2 = 0.75\\times0.268\\times35 = 7.03$ kN/m على الحوائط 2 (4.5 م) — الحوائط الطويلة بتبعت أفقي قليل."},{en:"Corner: $K = 0.5I/4.5 = 0.111I$ and $0.5I/6 = 0.083I$ → D.f. 0.57 / 0.43. F.E.M.: $7.03\\times4.5^2/12 = 11.87$ and $-2.72\\times6^2/12 = -8.17$ kN.m. Balance $-2.11$ / $-1.59$ → $M_{corner} = 9.76$ kN.m.",ar:"الركن: $K = 0.5I/4.5 = 0.111I$ و $0.5I/6 = 0.083I$ ← D.f. = 0.57 / 0.43. عزوم التثبيت: $7.03\\times4.5^2/12 = 11.87$ و $-2.72\\times6^2/12 = -8.17$ kN.m. الاتزان $-2.11$ / $-1.59$ ← $M_{corner} = 9.76$ kN.m."},{en:"Mid-spans: walls 1 $2.72\\times6^2/8 - 9.76 = 2.50$, walls 2 $7.03\\times4.5^2/8 - 9.76 = 8.04$ kN.m. Tension: walls 1 carry $7.03\\times4.5/2 = 15.82$ kN, walls 2 carry $2.72\\times6/2 = 8.17$ kN.",ar:"نصوص البحور: الحوائط 1 $2.72\\times6^2/8 - 9.76 = 2.50$، والحوائط 2 $7.03\\times4.5^2/8 - 9.76 = 8.04$ kN.m. الشد: الحوائط 1 عليها $7.03\\times4.5/2 = 15.82$ kN، والحوائط 2 عليها $2.72\\times6/2 = 8.17$ kN."}]},{t:"lab",lab:"tank",height:480,props:{preset:"rectHz",missions:o,defaultTab:"results"},caption:{en:"The frame at h/4 in plan, drawn solid and bent (exaggerated). Below, its B.M.D. and N.F.D.: every wall in tension.",ar:"الإطار عند h/4 في المسقط، مرسوم مصمت ومنحني (بمبالغة). وتحت، منحنى العزوم والقوى العمودية: كل الحوائط شد."}},{t:"quiz",q:{kind:"mcq",q:{en:"The walls of the horizontal frame at h/4 carry…",ar:"حوائط الإطار الأفقي عند h/4 عليها…"},options:[{en:"tension, from the end shears of the walls they meet",ar:"شد، من قص أطراف الحوائط اللي بيقابلوها"},{en:"compression, because the water squeezes the frame",ar:"ضغط، علشان المية بتعصر الإطار"},{en:"no normal force at all",ar:"مفيش قوة عمودية خالص"}],answer:0,explain:{en:"The water pushes every wall outwards; at each corner the neighbouring wall holds it back by pulling — N = qL/2 of the perpendicular walls.",ar:"المية بتزق كل حائط لبرّه؛ وعند كل ركن الحائط اللي جنبه بيمسكه بالشد — N = qL/2 بتاع الحوائط العمودية عليه."}}}]},{id:"cells",title:{en:"More joints: compartments, intermediate supports and closed tanks",ar:"عقد أكتر: العنابر والركائز الوسطانية والخزانات المقفولة"},blocks:[{t:"p",text:{en:"A strip gets more joints when the floor also rests on an **intermediate line of columns** or on an **intermediate wall**, and when a tank is divided into **compartments**. Balance all the joints together, carry half over to the far ends, balance again: two cycles, as by hand. A **symmetric middle span** (the axis of symmetry cuts it) is a symmetric member: $K = 0.5I/L$, $FEM = wL^2/12$, no carry-over.",ar:"الشريحة بتاخد عقد أكتر لما الأرضية تتسند كمان على **صف أعمدة وسطاني** أو على **حائط وسطاني**، ولما الخزان يتقسم **عنابر**. وازن كل العقد مع بعض، ورحّل النص للأطراف البعيدة، ووازن تاني: دورتين زي الحل باليد. و**البحر الوسطاني المتماثل** (محور التماثل بيقطعه) عضو متماثل: $K = 0.5I/L$، و $FEM = wL^2/12$، من غير ترحيل."}},{t:"eq",tex:"M_{mid} = \\dfrac{wL^2}{8} - \\dfrac{M_{left} + M_{right}}{2},\\qquad Q_{left,\\,right} = \\dfrac{wL}{2} \\pm \\dfrac{M_{right} - M_{left}}{L}",caption:{en:"A span with different end moments (magnitudes, both hogging): the mid-span moment and the end shears — the larger shear at the end with the larger moment.",ar:"بحر عزوم أطرافه مختلفة (قيم مطلقة، الاتنين سالبين): عزم نص البحر وقص الأطراف — القص الأكبر عند الطرف اللي عزمه أكبر."}},{t:"p",text:{en:"Compartments bring a new **load case**: one compartment is emptied for cleaning while the next stays full. The intermediate wall then has water on one side only — it bends towards the empty compartment — and the floor of the empty compartment carries only its own weight. With all compartments full, the intermediate wall has water on both sides and hardly bends at all. Both cases must be checked.",ar:"العنابر بتجيب **حالة تحميل** جديدة: عنبر بيتفضّى للنضافة والتاني فاضل مليان. ساعتها الحائط الوسطاني عليه مية من ناحية واحدة — بينحني ناحية العنبر الفاضي — وأرضية العنبر الفاضي شايلة وزنها بس. ولما العنابر كلها مليانة، الحائط الوسطاني عليه مية من الناحيتين وتقريبًا مش بينحني. ولازم الحالتين يتراجعوا."}},{t:"p",text:{en:"A **closed tank** has its roof cast with the walls, so every joint is rigid — the roof, walls and floor make one closed frame: the roof carries its own weight and live load and hands end moments to the wall tops. The same table does it, only with more columns. Stopping after two cycles leaves the joints nearly — not exactly — balanced, so axial forces read from the end reactions may not close perfectly; balancing until convergence removes that.",ar:"**الخزان المقفول** سقفه مصبوب مع الحوائط، فكل العقد جاسئة — السقف والحوائط والأرضية بيعملوا إطار واحد مقفول: السقف شايل وزنه والحمل الحي وبيسلّم عزوم أطراف لرووس الحوائط. ونفس الجدول بيحلها بس بأعمدة أكتر. والوقوف بعد دورتين بيسيب العقد متزنة تقريبًا — مش بالظبط — فالقوى المحورية المحسوبة من ردود الأفعال ممكن ما تقفلش بالظبط؛ والاتزان لحد النهاية بيشيل ده."}},{t:"steps",items:[{en:"A tank of two compartments 4.5 × 4.0 m (axes), 3.0 m deep, 250 mm walls and floor; compartment B empty. Strip 2 runs through both: end wall ab, floor bc (A), intermediate wall cf, floor cd (B), end wall de. Walls 2 (4.0 m): $\\alpha_2 = 0.760$; the floor spans 4.5 m with $\\beta_f = 4^4/(4^4 + 4.5^4) = 0.384$.",ar:"خزان بعنبرين 4.5 × 4.0 م (محاور)، وعمقه 3.0 م، والحوائط والأرضية 250 مم؛ والعنبر B فاضي. الشريحة 2 معدية على الاتنين: الحائط الطرفي ab، والأرضية bc (A)، والحائط الوسطاني cf، والأرضية cd (B)، والحائط الطرفي de. الحوائط 2 (4.0 م): $\\alpha_2 = 0.760$؛ والأرضية على بحر 4.5 م بـ $\\beta_f = 4^4/(4^4 + 4.5^4) = 0.384$."},{en:"Loads: walls $0.760\\times30 = 22.79$ + bottom triangle 7.21 kN/m; floor A $0.384\\times36.25 = 13.93$, floor B $0.384\\times6.25 = 2.40$ kN/m. F.E.M.: $FEM_{ba} = 22.79\\times3^2/15 + 7.21\\times3^2/117 = 14.23$; $\\mp13.93\\times4.5^2/12 = \\mp23.51$; $FEM_{cf} = -14.23$; $\\mp2.40\\times4.5^2/12 = \\mp4.05$ kN.m.",ar:"الأحمال: الحوائط $0.760\\times30 = 22.79$ + مثلث سفلي 7.21 kN/m؛ وأرضية A $0.384\\times36.25 = 13.93$، وأرضية B $0.384\\times6.25 = 2.40$ kN/m. عزوم التثبيت: $FEM_{ba} = 22.79\\times3^2/15 + 7.21\\times3^2/117 = 14.23$؛ و $\\mp13.93\\times4.5^2/12 = \\mp23.51$؛ و $FEM_{cf} = -14.23$؛ و $\\mp2.40\\times4.5^2/12 = \\mp4.05$ kN.m."}]},{t:"table",head:["","ba","bc","cb","cf","cd","dc","de"],rows:[["D.f.","0.53","0.47","0.32","0.36","0.32","0.47","0.53"],["F.E.M.","14.23","−23.51","23.51","−14.23","−4.05","4.05","0"],["Bal.M.","4.92","4.36","−1.67","−1.88","−1.67","−1.91","−2.15"],["C.O.M.","0","−0.84","2.18","0","−0.95","−0.84","0"],["Bal.M.","0.44","0.39","−0.39","−0.44","−0.39","0.39","0.44"],["M_f","19.59","−19.59","23.63","−16.55","−7.07","1.71","−1.71"]],caption:{en:"Two cycles. Balanced until it converges: 19.74, 23.72, −16.74, −6.98 and 1.55 — the two-cycle table is within 0.19 kN.m.",ar:"دورتين. ولو اتوازن لحد النهاية: 19.74 و 23.72 و −16.74 و −6.98 و 1.55 — جدول الدورتين في حدود 0.19 kN.m."}},{t:"steps",items:[{en:"The intermediate wall has 16.55 kN.m at its foot with tension on the full side, and bulges towards B with a span moment of 5.16 kN.m. The floor of A has 23.63 kN.m over the intermediate wall (water face in tension) and 13.69 kN.m in its span.",ar:"الحائط الوسطاني عليه 16.55 kN.m عند رجله والشد ناحية العنبر المليان، وبيتنفخ ناحية B بعزم بحر 5.16 kN.m. وأرضية A عليها 23.63 kN.m فوق الحائط الوسطاني (شد على وش المية) و 13.69 kN.m في بحرها."}]},{t:"lab",lab:"tank",height:480,props:{preset:"cells",missions:n,defaultTab:"results"},caption:{en:"Two compartments, B empty: the intermediate wall bends towards the empty side. Step through the table below, then let it converge.",ar:"عنبرين، و B فاضي: الحائط الوسطاني بينحني ناحية الفاضي. امشي في الجدول تحت صف صف، وبعدين سيبه يتزن."}},{t:"quiz",q:{kind:"num",q:{en:"A symmetric middle span of 5 m carries 30 kN/m. Its fixed-end moment in the table (kN.m)?",ar:"بحر وسطاني متماثل 5 م عليه 30 kN/m. عزم التثبيت بتاعه في الجدول (kN.m)؟"},answer:62.5,tol:.003,unit:"kN.m",explain:{en:"$FEM = wL^2/12 = 30\\times25/12 = 62.5$ kN.m, with $K = 0.5I/5$ and no carry-over.",ar:"$FEM = wL^2/12 = 30\\times25/12 = 62.5$ kN.m، و $K = 0.5I/5$ من غير ترحيل."}}}]},{id:"soil",title:{en:"Tanks rested on soil and partly buried tanks",ar:"الخزانات المرتكزة على التربة والمدفونة جزئيًا"},blocks:[{t:"p",text:{en:"A tank that rests on the ground uses its floor as a **footing for the whole tank**. The floor is made thick — at least **400–500 mm** — so that the soil pressure under it is uniform; the walls are usually **250–300 mm**, so $I_{floor}$ is some **4 to 8 times** $I_{wall}$. Collect every load on the strip, spread it over the floor, and take away what the floor carries directly (its own weight and the water on it) — that goes straight into the soil and does not bend the floor:",ar:"الخزان المرتكز على الأرض بيستخدم أرضيته **كقاعدة للخزان كله**. الأرضية بتتعمل تخينة — على الأقل **400–500 مم** — علشان ضغط التربة تحتها يبقى منتظم؛ والحوائط غالبًا **250–300 مم**، فـ $I_{floor}$ حوالي **4 لـ 8 أضعاف** $I_{wall}$. اجمع كل الأحمال على الشريحة، وافرشها على الأرضية، واطرح اللي الأرضية شايلاه مباشرة (وزنها والمية اللي عليها) — ده بينزل على التربة على طول ومش بيحني الأرضية:"}},{t:"eq",tex:"W_{total} = \\sum W,\\qquad f_{gross} = \\dfrac{W_{total}}{L\\times1.0},\\qquad f_{net} = f_{gross} - w_{direct}\\ (\\uparrow)"},{t:"p",text:{en:"What is left, $f_{net}$, comes from the weights of the walls and of the roof: it pushes the floor **upwards** between the walls, so the floor bends the other way round — **tension on its top face** (the water face) at mid-span. The floor reaction is **not** handed to the wall any more (the floor sits on the soil): the wall carries only the vertical loads above each level, in **compression**. When one compartment is empty the resultant moves towards the full one; a stiff floor then gives a trapezoid, $f = W/A \\pm 6We/L^2$, as under any footing.",ar:"اللي بيفضل، $f_{net}$، جاي من أوزان الحوائط والسقف: بيزق الأرضية **لفوق** بين الحوائط، فالأرضية بتنحني بالعكس — **شد على وشها العلوي** (وش المية) في نص البحر. ورد فعل الأرضية **مش** بيتسلّم للحائط تاني (الأرضية قاعدة على التربة): الحائط شايل بس الأحمال الرأسية اللي فوق كل منسوب، **ضغط**. ولما عنبر يكون فاضي المحصلة بتتزحزح ناحية المليان؛ والأرضية الجاسئة ساعتها بتدّي شبه منحرف، $f = W/A \\pm 6We/L^2$، زي تحت أي قاعدة."}},{t:"steps",items:[{en:"A tank 7.0 × 5.0 m on the soil, 3.0 m deep, walls 250 mm, floor 450 mm ($I_f/I_w = (450/250)^3 = 5.83$), 15 kN/m from the roof on each wall top. Walls 1 are 7.0 m long, more than twice their height: one-way, $\\alpha_1 = 1$.",ar:"خزان 7.0 × 5.0 م على التربة، وعمقه 3.0 م، والحوائط 250 مم، والأرضية 450 مم ($I_f/I_w = (450/250)^3 = 5.83$)، و 15 kN/m من السقف على راس كل حائط. الحوائط 1 طولها 7.0 م، أكتر من ضعف ارتفاعها: اتجاه واحد، $\\alpha_1 = 1$."},{en:"Strip 1 across 5 m: each wall $15 + 25\\times0.25\\times3 = 33.75$ kN; floor $w_2 = 0.45\\times25 + 30 = 41.25$ kN/m. $W_{total} = 2\\times33.75 + 41.25\\times5 = 273.75$ kN, $f_{gross} = 54.75$, $f_{net} = 54.75 - 41.25 = 13.5$ kN/m² upwards.",ar:"الشريحة 1 على 5 م: كل حائط $15 + 25\\times0.25\\times3 = 33.75$ kN؛ والأرضية $w_2 = 0.45\\times25 + 30 = 41.25$ kN/m. $W_{total} = 2\\times33.75 + 41.25\\times5 = 273.75$ kN، و $f_{gross} = 54.75$، و $f_{net} = 54.75 - 41.25 = 13.5$ kN/m² لفوق."},{en:"D.f.: $0.75/3 = 0.25$ against $0.5\\times5.83/5 = 0.583$ → 0.30 / 0.70. F.E.M.: $30\\times3^2/15 = 18.00$; the upward load gives $+13.5\\times5^2/12 = +28.13$. Balance $-13.84$ / $-32.29$ → $M_f = 4.16$ kN.m.",ar:"معاملات التوزيع: $0.75/3 = 0.25$ قصاد $0.5\\times5.83/5 = 0.583$ ← 0.30 / 0.70. عزوم التثبيت: $30\\times3^2/15 = 18.00$؛ والحمل اللي لفوق بيدّي $+13.5\\times5^2/12 = +28.13$. الاتزان $-13.84$ / $-32.29$ ← $M_f = 4.16$ kN.m."},{en:"Wall: $R_a = 13.61$, $R_b = 31.39$ kN, zero shear 1.65 m down, $M^+ = 14.97$ kN.m (dry face). Floor: $-(13.5\\times5^2/8 + 4.16) = -46.35$ kN.m — **top face in tension**; floor tension 31.39 kN; wall compression 15 kN at the top, 33.75 kN at the foot.",ar:"الحائط: $R_a = 13.61$، و $R_b = 31.39$ kN، والقص صفر على 1.65 م لتحت، و $M^+ = 14.97$ kN.m (الوش الناشف). الأرضية: $-(13.5\\times5^2/8 + 4.16) = -46.35$ kN.m — **شد على الوش العلوي**؛ وشد الأرضية 31.39 kN؛ وضغط الحائط 15 kN عند الراس و 33.75 kN عند الرجل."}]},{t:"lab",lab:"tank",height:480,props:{preset:"rested",missions:r,defaultTab:"results"},caption:{en:"The rested tank: the floor bends upwards — its top (water) face turns blue at mid-span.",ar:"الخزان المرتكز: الأرضية بتنحني لفوق — وشها العلوي (وش المية) بيبقى أزرق في نص البحر."}},{t:"p",text:{en:"**Partly buried tanks.** Below the ground the backfill presses on the walls from outside, with a lateral earth pressure that grows with depth ($K_a\\gamma_s z$; the lab takes $K_a\\gamma_s = 6$ kN/m³). Two cases govern: the tank **full before the backfill** is placed (the water pushes out) and the tank **empty with the backfill** (the earth pushes in). The h/4 rule holds at every rigid edge: a buried wall cast into a floor above and a floor below gets the extra vertical share at **both** ends. A tank whose lower storey is buried (a water tank over an underground room) works the same way: the lower walls take earth pressure and the lower floor takes the net soil pressure of the whole tank.",ar:"**الخزانات المدفونة جزئيًا.** تحت منسوب الأرض الردم بيضغط على الحوائط من برّه، بضغط تربة جانبي بيزيد مع العمق ($K_a\\gamma_s z$؛ والمعمل بياخد $K_a\\gamma_s = 6$ kN/m³). وفيه حالتين بيحكموا: الخزان **مليان قبل الردم** (المية بتزق لبرّه) والخزان **فاضي بعد الردم** (التربة بتزق لجوّه). وقاعدة h/4 بتنطبق عند كل حافة جاسئة: الحائط المدفون المصبوب مع أرضية فوقه وأرضية تحته بياخد النصيب الرأسي الزيادة عند **الطرفين**. والخزان اللي دوره السفلي مدفون (خزان مية فوق أوضة تحت الأرض) بيشتغل بنفس الطريقة: الحوائط السفلية بتاخد ضغط التربة والأرضية السفلية بتاخد صافي ضغط التربة للخزان كله."}},{t:"lab",lab:"tank",height:480,props:{preset:"buried",missions:i,defaultTab:"results"},caption:{en:"An empty tank buried 2.5 m: the earth bends the walls inwards — the tension moves to the soil face at the base.",ar:"خزان فاضي مدفون 2.5 م: التربة بتحني الحوائط لجوّه — الشد بيروح للوش اللي ناحية التربة عند القاعدة."}},{t:"quiz",q:{kind:"num",q:{en:"A 5 m strip of a rested tank: each wall with its roof share weighs 20 kN. f_net under the floor (kN/m²)?",ar:"شريحة 5 م في خزان مرتكز: كل حائط بنصيبه من السقف وزنه 20 kN. قيمة f_net تحت الأرضية (kN/m²)؟"},answer:8,tol:.003,unit:"kN/m²",explain:{en:"The floor load cancels itself; what bends the floor is $(20 + 20)/5 = 8$ kN/m², upwards.",ar:"حمل الأرضية بيلغي نفسه؛ واللي بيحني الأرضية $(20 + 20)/5 = 8$ kN/m² لفوق."}}}]},{id:"staging",title:{en:"Counterforts and the staging under wind",ar:"الدعامات (Counterforts) والأعمدة تحت الرياح"},blocks:[{t:"p",text:{en:"Very tall walls are stiffened by **counterforts**: vertical ribs inside the tank. The wall panels span horizontally between them and hand their reactions over, so each counterfort is a **vertical cantilever** loaded by a triangle rising to its largest value at $h/4$ above the floor (the h/4 rule again) and dropping to zero at the floor. Its base moment $M_{cant}$ passes into the floor. When the counterfort stands over a column, the floor reaction there goes straight into the column: **the counterfort carries no normal force**.",ar:"الحوائط العالية جدًا بتتقوّى بـ **دعامات (Counterforts)**: ضلوع رأسية جوّه الخزان. ألواح الحائط بتشيل أفقي بينها وبتسلّمها ردود أفعالها، فكل دعامة **كابولي رأسي** عليه مثلث بيكبر لأكبر قيمة عند $h/4$ فوق الأرضية (قاعدة h/4 تاني) وبيقل لصفر عند الأرضية. وعزم قاعدته $M_{cant}$ بيعدّي للأرضية. ولما الدعامة تكون فوق عمود، رد فعل الأرضية هناك بينزل على العمود على طول: **الدعامة مالهاش قوة عمودية**."}},{t:"eq",tex:"FEM_c = \\dfrac{wL^2}{8} - \\dfrac{M_{cant}}{2}",caption:{en:"The floor span b–c, hinged over the column at b where it receives M_cant, fixed at c.",ar:"بحر الأرضية b–c، مفصلي فوق العمود عند b حيث بياخد M_cant، وثابت عند c."}},{t:"steps",items:[{en:"A counterfort 4.0 m high: 0 → 60 kN/m over the upper 3.0 m, back to 0 over the bottom 1.0 m, and 20 kN at the top. $M_{cant} = 90\\times2.0 + 30\\times0.67 + 20\\times4 = 180 + 20 + 80 = 280$ kN.m; base shear $90 + 30 + 20 = 140$ kN.",ar:"دعامة ارتفاعها 4.0 م: 0 ← 60 kN/m على الـ 3.0 م العلوية، وترجع لـ 0 على الـ 1.0 م السفلية، و 20 kN عند الراس. $M_{cant} = 90\\times2.0 + 30\\times0.67 + 20\\times4 = 180 + 20 + 80 = 280$ kN.m؛ وقص القاعدة $90 + 30 + 20 = 140$ kN."},{en:"Floor: b–c 4.0 m with 120 kN/m, then a symmetric middle span of 4.0 m. $FEM_{cb} = 120\\times4^2/8 - 280/2 = 100$, $FEM_{cd} = -120\\times4^2/12 = -160$ kN.m; D.f. $0.75/4$ against $0.5/4$ → 0.6 / 0.4; $M_c = 100 + 0.6\\times60 = 136$ kN.m; middle span $240 - 136 = 104$ kN.m; floor tension 140 kN.",ar:"الأرضية: b–c طولها 4.0 م عليها 120 kN/m، وبعدها بحر وسطاني متماثل 4.0 م. $FEM_{cb} = 120\\times4^2/8 - 280/2 = 100$، و $FEM_{cd} = -120\\times4^2/12 = -160$ kN.m؛ ومعاملات التوزيع $0.75/4$ قصاد $0.5/4$ ← 0.6 / 0.4؛ و $M_c = 100 + 0.6\\times60 = 136$ kN.m؛ والبحر الوسطاني $240 - 136 = 104$ kN.m؛ وشد الأرضية 140 kN."}]},{t:"p",text:{en:"An **elevated tank** stands on a **staging**: columns braced by beams at several levels. Under wind the staging is a multi-storey frame that sways — too long for moment distribution by hand. The **approximate method** assumes **hinges** where the moment is (nearly) zero: at the **middle of every beam**; in the columns **2/3 h below the tank** in the top storey (the tank bottom is very stiff and fixes the column tops), at **h/2** in the storeys between, and **1/3 h below the lowest beam** over a fixed base (at the base itself when it is pinned). The frame becomes statically determinate:",ar:"**الخزان العالي** واقف على **أعمدة**: أعمدة متربطة بكمرات عند كذا منسوب. وتحت الرياح الأعمدة دي إطار متعدد الأدوار بيتحرك جنب — طويل على توزيع العزوم باليد. **الطريقة التقريبية** بتفترض **مفصلات** مكان ما العزم (تقريبًا) صفر: في **نص كل كمرة**؛ وفي الأعمدة **2/3 h تحت الخزان** في الدور العلوي (قاع الخزان جاسئ جدًا وبيثبّت رووس الأعمدة)، وعند **h/2** في الأدوار اللي في النص، و **1/3 h تحت آخر كمرة** فوق قاعدة ثابتة (وعند القاعدة نفسها لو مفصلية). والإطار بيبقى محدد استاتيكيًا:"}},{t:"eq",tex:"Q_{col} = \\dfrac{\\sum H}{2},\\qquad N_{col} = \\pm\\dfrac{\\sum H_i\\,z_i}{a},\\qquad M_{col} = Q_{col}\\times d_{hinge},\\qquad M_{beam} = \\sum M_{col},\\qquad Q_{beam} = \\dfrac{M_{beam}}{a/2}",caption:{en:"z_i: height of each load above the hinge level; a: the bay. The windward column is pulled (+), the leeward one pushed (−). A beam carries half the load of its level in compression.",ar:"z_i: ارتفاع كل حمل فوق منسوب المفصل؛ و a: البحر. العمود اللي ناحية الرياح مشدود (+)، والتاني مضغوط (−). والكمرة شايلة نص حمل منسوبها ضغط."}},{t:"steps",items:[{en:"A one-bay staging, $a = 4.0$ m, three storeys of 3.5 m, fixed bases; wind 30 kN at the tank, 12 kN at each bracing level. Hinges: 2.33 m below the tank; mid-height of storey 2; 1.17 m below the lowest beam.",ar:"أعمدة بباكية واحدة، $a = 4.0$ م، وتلات أدوار كل واحد 3.5 م، وقواعد ثابتة؛ والرياح 30 kN عند الخزان و 12 kN عند كل منسوب تربيط. المفصلات: 2.33 م تحت الخزان؛ ونص ارتفاع الدور 2؛ و 1.17 م تحت آخر كمرة."},{en:"Column shears 15, 21, 27 kN. Axial: $30\\times2.33/4 = 17.5$; $(30\\times5.25 + 12\\times1.75)/4 = 44.63$; $(30\\times8.17 + 12\\times4.67 + 12\\times1.17)/4 = 78.75$ kN.",ar:"قص الأعمدة 15 و 21 و 27 kN. المحوري: $30\\times2.33/4 = 17.5$؛ و $(30\\times5.25 + 12\\times1.75)/4 = 44.63$؛ و $(30\\times8.17 + 12\\times4.67 + 12\\times1.17)/4 = 78.75$ kN."},{en:"Column moments: 35 / 17.5; 36.75 / 36.75; 31.5 / 63 kN.m (the base). Beams: 35; $17.5 + 36.75 = 54.25$; $36.75 + 31.5 = 68.25$ kN.m, beam shears 17.5, 27.13, 34.13 kN — which add up to the column axial forces.",ar:"عزوم الأعمدة: 35 / 17.5؛ و 36.75 / 36.75؛ و 31.5 / 63 kN.m (القاعدة). والكمرات: 35؛ و $17.5 + 36.75 = 54.25$؛ و $36.75 + 31.5 = 68.25$ kN.m، وقص الكمرات 17.5 و 27.13 و 34.13 kN — ومجموعهم بيدّي القوى المحورية في الأعمدة."}]},{t:"lab",lab:"tank",height:480,props:{preset:"staging",missions:l,defaultTab:"steps"},caption:{en:"The staging of the example: yellow spheres at the assumed hinges; the 3-D frame is solved exactly for its (exaggerated) sway.",ar:"أعمدة المثال: الكور الصفرا عند المفصلات المفترضة؛ والإطار الـ 3D متحل بالظبط علشان حركته الجانبية (بمبالغة)."}},{t:"quiz",q:{kind:"num",q:{en:"Two columns 5 m apart; a wind load of 50 kN acts 3 m above the hinge level of a storey (no other load). Axial force in each column (kN)?",ar:"عمودين بينهم 5 م؛ وحمل رياح 50 kN شغال على 3 م فوق منسوب المفصلات في دور (مفيش أحمال تانية). القوة المحورية في كل عمود (kN)؟"},answer:30,tol:.003,unit:"kN",explain:{en:"$N = 50\\times3/5 = 30$ kN — tension on the windward column, compression on the leeward one.",ar:"$N = 50\\times3/5 = 30$ kN — شد على العمود اللي ناحية الرياح، وضغط على التاني."}}}]},{id:"apply",title:{en:"Your building: the ground reservoir",ar:"مبناك: الخزان الأرضي"},blocks:[{t:"p",text:{en:"The water tower needs water to pump up: your site gets a **ground reservoir** behind the tower. It **rests on the soil** — its floor on a blinding layer 0.30 m below the ground (so little backfill that its pressure is ignored). Two compartments of **2.8 × 3.2 m** (axes) side by side, so one can be emptied and cleaned while the other keeps the supply; water **2.4 m** deep; walls **250 mm**, floor **400 mm** (the rested-tank rules), a **150 mm** roof slab that holds the wall tops. Volume: $2\\times2.55\\times2.95\\times2.4 = 36.1$ m³ — the tower holds 27.7 m³.",ar:"برج المية محتاج مية يطلّعها: موقعك بياخد **خزان أرضي** ورا البرج. **مرتكز على التربة** — أرضيته على طبقة خرسانة نظافة 0.30 م تحت الأرض (ردم قليل لدرجة إن ضغطه بيتهمل). عنبرين **2.8 × 3.2 م** (محاور) جنب بعض، علشان واحد يتفضّى ويتنضف والتاني يفضل مغذّي؛ وعمق المية **2.4 م**؛ والحوائط **250 مم**، والأرضية **400 مم** (قواعد الخزانات المرتكزة)، وبلاطة سقف **150 مم** ماسكة رووس الحوائط. الحجم: $2\\times2.55\\times2.95\\times2.4 = 36.1$ م³ — والبرج بيشيل 27.7 م³."}},{t:"steps",items:[{en:"Shares: walls 1 (2.8 m panels between the end and the intermediate wall): $\\alpha_1 = 2.8^4/(2.8^4 + 2.4^4) = 0.649$; walls 2 (3.2 m): $\\alpha_2 = 0.760$. Roof $0.15\\times25 + 1.5 + 1.0 = 6.25$ kN/m² → 3.7 kN/m on walls 1, 5.5 kN/m on walls 2.",ar:"الأنصبة: الحوائط 1 (ألواح 2.8 م بين الحائط الطرفي والوسطاني): $\\alpha_1 = 2.8^4/(2.8^4 + 2.4^4) = 0.649$؛ والحوائط 2 (3.2 م): $\\alpha_2 = 0.760$. والسقف $0.15\\times25 + 1.5 + 1.0 = 6.25$ kN/m² ← 3.7 kN/m على الحوائط 1، و 5.5 kN/m على الحوائط 2."},{en:"Strip 1 (across 3.2 m, both compartments full): each wall $3.7 + 25\\times0.25\\times2.4 = 18.7$ kN; $w_2 = 0.4\\times25 + 24 = 34$ kN/m; $W = 2\\times18.7 + 34\\times3.2 = 146.2$ kN, $f_{gross} = 45.69$, $f_{net} = 11.69$ kN/m² upwards.",ar:"الشريحة 1 (على 3.2 م، والعنبرين مليانين): كل حائط $3.7 + 25\\times0.25\\times2.4 = 18.7$ kN؛ و $w_2 = 0.4\\times25 + 24 = 34$ kN/m؛ و $W = 2\\times18.7 + 34\\times3.2 = 146.2$ kN، و $f_{gross} = 45.69$، و $f_{net} = 11.69$ kN/m² لفوق."},{en:"D.f. 0.33 / 0.67 ($I_f/I_w = 4.10$). F.E.M.: $15.59\\times2.4^2/15 + 8.41\\times2.4^2/117 = 6.40$ and $+11.69\\times3.2^2/12 = +9.97$ kN.m → $M_f = 1.00$ kN.m. Wall: $M^+ = 5.48$ kN.m, 1.36 m below the roof. Floor mid-span 15.96 kN.m with the **top face in tension**, and 15.20 kN of tension.",ar:"معاملات التوزيع 0.33 / 0.67 ($I_f/I_w = 4.10$). عزوم التثبيت: $15.59\\times2.4^2/15 + 8.41\\times2.4^2/117 = 6.40$ و $+11.69\\times3.2^2/12 = +9.97$ kN.m ← $M_f = 1.00$ kN.m. الحائط: $M^+ = 5.48$ kN.m على 1.36 م تحت السقف. ونص بحر الأرضية 15.96 kN.m و**الشد على وشها العلوي**، و 15.20 kN شد."},{en:"Strip 2 with compartment B empty: the soil pressure becomes a trapezoid, 51.96 → 15.96 kN/m² ($e = 0.49$ m towards A). The intermediate wall gets 6.95 kN.m at its foot (tension on A's side), the end wall of A 4.67 kN.m, the floor of B 15.99 kN.m over the intermediate wall (bottom face).",ar:"الشريحة 2 والعنبر B فاضي: ضغط التربة بيبقى شبه منحرف، 51.96 ← 15.96 kN/m² ($e = 0.49$ م ناحية A). الحائط الوسطاني بياخد 6.95 kN.m عند رجله (الشد ناحية A)، والحائط الطرفي لـ A بياخد 4.67 kN.m، وأرضية B بتاخد 15.99 kN.m فوق الحائط الوسطاني (الوش السفلي)."},{en:"Frame at h/4 (both full): $q_1 = 0.75\\times0.351\\times24 = 6.31$, $q_2 = 0.75\\times0.240\\times24 = 4.33$ kN/m; corners 3.82 kN.m, the walls at the intermediate wall 4.27 kN.m; tension 6.92 and 8.67 kN. Under the whole tank: $W = 1040$ kN on 6.25 × 3.85 m → 43.2 kN/m², far below the allowable 150.",ar:"الإطار عند h/4 (الاتنين مليانين): $q_1 = 0.75\\times0.351\\times24 = 6.31$، و $q_2 = 0.75\\times0.240\\times24 = 4.33$ kN/m؛ والأركان 3.82 kN.m، والحوائط عند الحائط الوسطاني 4.27 kN.m؛ والشد 6.92 و 8.67 kN. وتحت الخزان كله: $W = 1040$ kN على 6.25 × 3.85 م ← 43.2 kN/m²، أقل بكتير من المسموح 150."}]},{t:"lab",lab:"tank",height:480,props:{preset:"reservoir",missions:h,defaultTab:"results"},caption:{en:"The reservoir of your building in the Water Tank Lab: strip 2 with compartment B empty.",ar:"خزان مبناك في معمل الخزانات: الشريحة 2 والعنبر B فاضي."}},{t:"widget",w:"building",props:{focus:"RS-WM",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","tower-dome","reservoir"]}},{t:"quiz",q:{kind:"mcq",q:{en:"Why is the top face of the reservoir floor in tension at mid-span?",ar:"ليه الوش العلوي لأرضية الخزان عليه شد في نص البحر؟"},options:[{en:"the floor rests on the soil: f_net from the walls and roof pushes it up between the walls",ar:"الأرضية قاعدة على التربة: f_net من الحوائط والسقف بيزقها لفوق بين الحوائط"},{en:"the water weighs more than the walls",ar:"المية أتقل من الحوائط"},{en:"the walls are hinged at the top",ar:"الحوائط مفصلية من فوق"}],answer:0,explain:{en:"Water and floor weight go straight into the soil; only $f_{net} = 11.69$ kN/m² bends the floor, upwards — the reverse of an elevated tank.",ar:"المية ووزن الأرضية بينزلوا على التربة على طول؛ واللي بيحني الأرضية $f_{net} = 11.69$ kN/m² بس، لفوق — عكس الخزان العالي."}}}]}],quiz:[{kind:"num",q:{en:"Water pressure at the foot of a wall holding 3.6 m of water (kN/m²)?",ar:"ضغط المية عند رجل حائط شايل 3.6 م مية (kN/m²)؟"},answer:36,tol:.003,unit:"kN/m²",explain:{en:"$w_1 = \\gamma_w h = 10\\times3.6 = 36$ kN/m².",ar:"$w_1 = \\gamma_w h = 10\\times3.6 = 36$ kN/m²."}},{kind:"num",q:{en:"A cantilever channel wall 1.8 m high, full of water. M_b (kN.m per metre)?",ar:"حائط قناة كابولي ارتفاعه 1.8 م، مليان مية. M_b (kN.m للمتر)؟"},answer:9.72,tol:.003,unit:"kN.m",explain:{en:"$M_b = w_1h^2/6 = 18\\times1.8^2/6 = 9.72$ kN.m.",ar:"$M_b = w_1h^2/6 = 18\\times1.8^2/6 = 9.72$ kN.m."}},{kind:"mcq",q:{en:"The supports drawn under the corners of an open-channel strip are…",ar:"الركائز المرسومة تحت أركان شريحة القناة المفتوحة هي…"},options:[{en:"the walls themselves, working as upturned beams between the real columns",ar:"الحوائط نفسها، شغالة ككمرات مقلوبة بين الأعمدة الحقيقية"},{en:"columns under every metre of the channel",ar:"أعمدة تحت كل متر من القناة"},{en:"the soil under the floor",ar:"التربة تحت الأرضية"}],answer:0,explain:{en:"The wall is a deep beam carrying the floor; that is also why it is in tension (arch action).",ar:"الحائط كمرة عميقة شايلة الأرضية؛ وده برضه سبب إنه مشدود (عمل القوس)."}},{kind:"num",q:{en:"Fixed-end moment at the base of a wall 4 m high, hinged at the top, from a bottom-h/4 triangle of 10 kN/m (kN.m)?",ar:"عزم التثبيت عند قاعدة حائط ارتفاعه 4 م ومفصلي من فوق، من مثلث الربع السفلي 10 kN/m (kN.m)؟"},answer:1.368,tol:.003,unit:"kN.m",explain:{en:"$wh^2/117 = 10\\times16/117 = 1.368$ kN.m.",ar:"$wh^2/117 = 10\\times16/117 = 1.368$ kN.m."}},{kind:"num",q:{en:"In the frame at h/4 a 5 m wall carries 8 kN/m and its corners 10 kN.m. Its mid-span moment (kN.m)?",ar:"في الإطار عند h/4 حائط 5 م عليه 8 kN/m وأركانه 10 kN.m. عزم نص البحر (kN.m)؟"},answer:15,tol:.003,unit:"kN.m",explain:{en:"$8\\times5^2/8 - 10 = 25 - 10 = 15$ kN.m, tension on the dry face.",ar:"$8\\times5^2/8 - 10 = 25 - 10 = 15$ kN.m، شد على الوش الناشف."}},{kind:"tf",q:{en:"In a tank rested on soil, the walls hang the floor load and are therefore in tension.",ar:"في الخزان المرتكز على التربة، الحوائط شايلة حمل الأرضية وعلشان كده بتبقى شد."},answer:!1,explain:{en:"The floor sits on the soil; the walls carry only the loads above them, in compression.",ar:"الأرضية قاعدة على التربة؛ والحوائط شايلة الأحمال اللي فوقها بس، ضغط."}},{kind:"num",q:{en:"The loads on a 5 m strip of a rested tank add up to 300 kN. f_gross (kN/m²)?",ar:"الأحمال على شريحة 5 م في خزان مرتكز مجموعها 300 kN. f_gross (kN/m²)؟"},answer:60,tol:.003,unit:"kN/m²",explain:{en:"$300/(5\\times1.0) = 60$ kN/m².",ar:"$300/(5\\times1.0) = 60$ kN/m²."}},{kind:"num",q:{en:"A storey of a staging has a shear of 60 kN on two columns, the hinge 2 m below the beam. Column moment at the beam (kN.m)?",ar:"دور في الأعمدة عليه قص 60 kN على عمودين، والمفصل 2 م تحت الكمرة. عزم العمود عند الكمرة (kN.m)؟"},answer:60,tol:.003,unit:"kN.m",explain:{en:"$Q_{col} = 60/2 = 30$ kN, $M = 30\\times2 = 60$ kN.m.",ar:"$Q_{col} = 60/2 = 30$ kN، و $M = 30\\times2 = 60$ kN.m."}}]};export{m as default};
